t.script:
(function () {
    function isEditing() {
        return document.body.classList.contains('editor_enable') ||
            /[?&]enable_editor=/.test(window.location.search) ||
            window.frameElement !== null;
    }
    function removeCopies() {
        document.querySelectorAll('header#top .ay-preorder-nav').forEach(function (el) { el.remove(); });
    }
    function inject() {
        removeCopies();
        if (isEditing()) { return; }
        var src = document.querySelector('.ay-preorder-src a');
        if (!src) { return; }
        var targets = [
            document.querySelector('header#top #o_main_nav > ul.navbar-nav:last-of-type'),
            document.querySelector('header#top .o_header_mobile_buttons_wrap')
        ];
        targets.forEach(function (ul) {
            if (!ul) { return; }
            var li = document.createElement('li');
            li.className = 'nav-item ay-preorder-nav';
            var a = src.cloneNode(true);
            a.classList.add('ay-preorder-btn');
            li.appendChild(a);
            ul.appendChild(li);
        });
    }
    function start() {
        inject();
        new MutationObserver(function () {
            if (document.body.classList.contains('editor_enable')) { removeCopies(); }
        }).observe(document.body, { attributes: true, attributeFilter: ['class'] });
    }
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', start);
    } else {
        start();
    }
})();
